// Mice Hubless recognises by USB id, including ones it has no driver for yet. Generated by tools/build-catalog.py
// from OpenRazer and libratbag device data plus models verified here; see data/mice.json.
import type { CatalogModel } from '@shared/types'
import data from '../../data/mice.json'

const models = (data as { models: CatalogModel[] }).models
const byId = new Map<string, CatalogModel>()
for (const m of models) for (const i of m.ids) byId.set(`${i.vid}:${i.pid}`, m)

export function lookup(vid: number, pid: number): CatalogModel | undefined {
  return byId.get(`${vid}:${pid}`)
}

export const catalogSize = () => ({ models: models.length, ids: byId.size })
